// Generated By: Claude Code (Claude Opus 4.6)
//
// Workflow script for review skill concern agent dispatch.
// Schema enforcement via agent(schema:) — structural, not persuasive.
//
// Workflow tool serializes args as a JSON string. Use JSON.parse(args) to recover.
//
// args (JSON string): {
//   agentOutputSchema: object,    // resolved agent-output schema
//   concerns: [{concern, slug, model, scope}],  // concern axes to dispatch
//   dimensions: [{name, slug, scope}],
//   projectRoot: string,
//   pluginHome: string,
//   projectContext: {language, buildSystem, testFramework},
//   standards: string,            // local standards text (from CLAUDE.md etc)
//   prScope: string,              // PR scope output or empty
//   userGuidance: string,         // user guidance output or empty
//   allowlist: string,            // allowed commands text or empty
//   buildPrompt: string,          // prompt for build-checks agent
// }

export const meta = {
  name: 'review-concern-agents',
  description: 'Dispatch concern agents with schema-enforced structured output',
  phases: [
    { title: 'Build', detail: 'Run make check targets' },
    { title: 'Review', detail: 'Concern agents per dimension', model: 'sonnet' },
  ],
}

const config = JSON.parse(args)

// ponytail: concerns passed via args from SKILL.md, not hardcoded — supports light review (2 concerns) and dimension selection (subset of 7)
const CONCERNS = config.concerns

function buildConcernPrompt(concern, dimension) {
  const prScopeBlock = config.prScope ? '\nPR SCOPE:\n' + config.prScope + '\n' : ''
  const guidanceBlock = config.userGuidance ? '\nUSER GUIDANCE:\n' + config.userGuidance + '\n' : ''
  const standardsBlock = config.standards ? '\nLOCAL STANDARDS:\n' + config.standards + '\n' : ''
  const allowlistBlock = config.allowlist ? '\nALLOWED COMMANDS:\n' + config.allowlist + '\n' : ''
  const sharedInfra = dimension.scope.shared_infrastructure
    ? '\nThis dimension covers shared infrastructure files modified in the PR. Only report findings INTRODUCED or EXPOSED by this PR — not pre-existing issues.\n'
    : ''

  return `You are reviewing the project at ${config.projectRoot} for the **${concern.concern}** axis within the dimension **${dimension.name}** (slug: ${dimension.slug}).

DIMENSION SCOPE (confine your review to this):
${JSON.stringify(dimension.scope)}
${sharedInfra}
If you notice issues clearly outside this scope, list them under cross_cutting_observations but do not investigate deeply.

PROJECT CONTEXT:
- Language: ${config.projectContext.language}
- Build system: ${config.projectContext.buildSystem}
- Test framework: ${config.projectContext.testFramework}
${allowlistBlock}${standardsBlock}${prScopeBlock}${guidanceBlock}
METHODOLOGY:
Phase 1 — Establish baseline patterns:
Read enough code in scope to understand the project's existing conventions for the ${concern.concern} axis.

Phase 2 — Assess against baseline:
Evaluate whether the codebase follows its own patterns consistently. Flag deviations, gaps, and concrete issues.

OUTPUT:
Your output is defined by the StructuredOutput tool's input schema. Read that schema — it is the spec. Every required field, enum value, and description is there. Key points:

- Set agent_id to "${concern.slug}/${dimension.slug}"
- Each finding has five categorical dimensions (runtime_scope, failure_mode, evidence_quality, trace_origin, effort_to_fix) — each requires a value AND a _justification string. Read the enum descriptions in the schema for classification guidance.
- Split test coverage gaps from production defects as separate findings with different dimensions.
- Do NOT drop speculative findings.
- When calling StructuredOutput, pass fields directly as root-level properties — do NOT wrap in a container key like "json_data", "output", or "parameter".

HARD EXCLUSIONS — never report:
- Style issues enforced by linters/formatters
- Missing tests for trivial code (getters/setters/data classes)
- Architecture concerns in scripts/ or one-off utilities
- Issues already caught by make targets
- Missing docstrings on private functions
- Generic best-practice advice not grounded in a specific code location
- Positive observations or praise — if suggested_fix says "no action needed", it is NOT a finding

PROHIBITED ACTIONS:
- Do NOT modify any source code or tests
- Do NOT execute the user's program
- Do NOT install or upgrade packages`
}

// Phase 1: Build checks
phase('Build')
const buildResult = await agent(config.buildPrompt, {
  label: 'build-checks',
  model: 'haiku',
  phase: 'Build',
})

// Phase 2: Concern agents with schema enforcement
phase('Review')
log('Dispatching ' + (config.dimensions.length * CONCERNS.length) + ' concern agents with schema enforcement')

const results = await parallel(
  config.dimensions.flatMap(dim =>
    CONCERNS.map(c => () =>
      agent(buildConcernPrompt(c, dim), {
        label: c.slug + '/' + dim.slug,
        model: c.model,
        phase: 'Review',
        schema: config.agentOutputSchema,
      }).then(output => output ? {
        concern_slug: c.slug,
        dimension_slug: dim.slug,
        filename: c.slug + '-' + dim.slug + '.json',
        output: output,
      } : null)
    )
  )
)

const succeeded = results.filter(Boolean)
const failed = results.length - succeeded.length
log(succeeded.length + '/' + results.length + ' agents returned valid output' + (failed > 0 ? ' (' + failed + ' failed)' : ''))

return {
  buildResult: buildResult,
  agentOutputs: succeeded,
  totalDispatched: results.length,
  failedCount: failed,
}
